CREATE TABLE IF NOT EXISTS indigenous_rights_framework (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), framework_code text UNIQUE NOT NULL, jurisdiction_region text NOT NULL DEFAULT 'Africa', country_code text, right_category text NOT NULL, safeguard_title text NOT NULL, safeguard_principle text NOT NULL, trigger_event text, required_review text, escalation_route text, legal_basis_note text, status text NOT NULL DEFAULT 'Active', version text NOT NULL DEFAULT '1.0', created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS indigenous_rights_region_idx ON indigenous_rights_framework(jurisdiction_region,country_code);
CREATE INDEX IF NOT EXISTS indigenous_rights_category_idx ON indigenous_rights_framework(right_category);
CREATE TABLE IF NOT EXISTS stakeholder_interests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), stakeholder_type text NOT NULL, name_or_identifier text NOT NULL, jurisdiction_region text, country_code text, interest_category text NOT NULL, legal_or_evidence_reference text, verification_status text NOT NULL DEFAULT 'Pending', notes text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS stakeholder_interests_jurisdiction_idx ON stakeholder_interests(jurisdiction_region,country_code);
CREATE INDEX IF NOT EXISTS stakeholder_interests_status_idx ON stakeholder_interests(verification_status);